    static let axis = EnergyAxis(offset: 0, scale: 0.01, size: 2048)

    static func input(_ elements: [String], locked: Bool, absorption: Bool) -> PooledQuantificationInput {
        var m = QuantificationMethod()
        m.elements = elements.map { QuantificationMethod.ElementState(symbol: $0, role: .quantify, isManual: false) }
        m.beamEnergyKeV = 200
        m.lockEnergyAxis = locked
        m.absorptionCorrection = absorption
        var meta = SpectrumImageMetadata(fileName: "EDS Spectrum Image.dm4", filePath: "", scanWidth: 46, scanHeight: 104,
                                         channelCount: 2048, energyOffsetEV: 0, energyDispersionEV: 10)
        meta.alphaTiltDegrees = 0.95
        meta.betaTiltDegrees = -5.86
        meta.beamEnergyKeV = 200
        return PooledQuantificationInput(counts: counts, axis: axis, method: m, metadata: meta, regionName: "Whole map",
                                         pixelCount: 46 * 104)
    }

    @Test func printTheFit() throws {
        var out: [String] = []
        for (elements, locked) in [(["O", "Al", "Y"], false), (["O", "Al", "Y"], true), (["O", "Al", "Y", "Au"], false), (["O", "Al", "Y", "C", "Au"], false)] {
            let q = try PooledQuantifier.run(Self.input(elements, locked: locked, absorption: true), tables: QuantificationTables.bundled())
            out.append("== \(elements) locked \(locked): axis offset \(q.usedAxis.offset) scale \(q.usedAxis.scale); refinement "
                       + "\(q.refinement.map { "R \($0.resolutionMnKaEV) conv \($0.converged) offset \($0.offset) scale \($0.scale)" } ?? "none")")
            for r in q.rows {
                out.append("  \(r.groupID): net \(r.net) ± \(r.sigma) atBound \(r.atBound) at% \(r.atomicPercent.map { String($0) } ?? "-") "
                           + "kFree \(r.kFreeRatio.map { String($0) } ?? "-") note \(r.lineNote ?? "") fail \(r.failure ?? "")")
            }
            let ch = (1480 ... 1510).filter { $0 % 3 == 0 }
            out.append("  Y Ka data/model/bg: " + ch.map { "\(Self.counts[$0])/\(String(format: "%.1f", q.plotModel[$0]))/\(String(format: "%.1f", q.plotBackground[$0]))" }.joined(separator: " "))
            out.append("  absorption \(q.absorption); refusal \(q.abundanceRefusal ?? "-"); warnings \(q.warnings)")
            out.append("  footer \(q.footerLines)")
        }
        Issue.record(Comment(rawValue: "YAlO3 fit:\n" + out.joined(separator: "\n")))
    }
